import{_ as o,o as t,c as a,ae as r}from"./chunks/framework.BX6FPmO9.js";const g=JSON.parse('{"title":"Figma MCP 架構與設計稿同步","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/figma-mcp.md","filePath":"architecture/figma-mcp.md"}'),i={name:"architecture/figma-mcp.md"};function n(s,e,l,c,d,m){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="figma-mcp-架構與設計稿同步" tabindex="-1">Figma MCP 架構與設計稿同步 <a class="header-anchor" href="#figma-mcp-架構與設計稿同步" aria-label="Permalink to &quot;Figma MCP 架構與設計稿同步&quot;">​</a></h1><p><strong>類型</strong>：reference | <strong>權重</strong>：2</p><p>本文件說明 Figma 與本專案的整合方式：MCP 定位、唯讀 tool 範圍、Token 轉換層、導入順序、<strong>Figma → AI 修改邊界</strong>，以及最小可行 MCP 架構要點。設計稿與 token 同步流程見 <a href="./design-system.html">design-system</a> 未來可選項；<strong>Token 的 canonical 在 repo</strong>，見 <a href="./../DESIGN_SYSTEM.html">DESIGN_SYSTEM.md</a>。</p><p><strong>原則</strong>：AI 可作為開發工具直接修改 repo，但所有變更仍以 <strong>repo 的 design system 與 token schema 為準</strong>，Figma 僅提供設計 context。誰擁有設計權威必須明確：repo 的 token schema、component API 與 layout system 為唯一權威，MCP 只提供 context。</p><hr><h2 id="一、figma-mcp-的本質" tabindex="-1">一、Figma MCP 的本質 <a class="header-anchor" href="#一、figma-mcp-的本質" aria-label="Permalink to &quot;一、Figma MCP 的本質&quot;">​</a></h2><p>目前常被混稱的三者：</p><table tabindex="0"><thead><tr><th>名稱</th><th>本質</th></tr></thead><tbody><tr><td>Figma API</td><td>官方 REST API</td></tr><tr><td>Figma Dev Mode</td><td>提供 code spec</td></tr><tr><td>Figma MCP server</td><td>社群 bridge</td></tr></tbody></table><p><strong>MCP server 本質上是 Figma API adapter</strong>：將 Figma API 包成 MCP protocol，供 Cursor 等 AI 工具以 tools/resources 方式讀取設計資料。並非官方產品，多為社群或自建。</p><hr><h2 id="二、mcp-tool-scope-唯讀" tabindex="-1">二、MCP Tool Scope：唯讀 <a class="header-anchor" href="#二、mcp-tool-scope-唯讀" aria-label="Permalink to &quot;二、MCP Tool Scope：唯讀&quot;">​</a></h2><p>MCP server <strong>僅暴露讀取操作</strong>，典型能力為：</p><ul><li><code>get_file(file_key?)</code> — 回傳檔案 meta / 節點樹摘要</li><li><code>get_variables(file_key?)</code> — 回傳 variable 清單（名稱、類型、mode、值）</li><li><code>get_component_spec(node_id | component_key)</code> — 回傳單一元件 spec（props、尺寸、樣式摘要），供對照 DESIGN_SYSTEM.md / ui 元件</li></ul><p><strong>不暴露</strong> <code>update_figma</code> 或任何寫入 Figma 的 API，避免 AI 直接改設計稿造成治理混亂。</p><hr><h2 id="三、token-transformation-layer" tabindex="-1">三、Token Transformation Layer <a class="header-anchor" href="#三、token-transformation-layer" aria-label="Permalink to &quot;三、Token Transformation Layer&quot;">​</a></h2><p>設計 token 同步是整個 workflow 最大技術風險。Figma Variables 與 CSS 變數格式不一致，需在 repo 內定義 <strong>Token transformation layer</strong>，涵蓋三點：</p><h3 id="_3-1-naming-strategy" tabindex="-1">3.1 Naming strategy <a class="header-anchor" href="#_3-1-naming-strategy" aria-label="Permalink to &quot;3.1 Naming strategy&quot;">​</a></h3><ul><li>Figma 常見：<code>color.primary.500</code>、<code>spacing.small</code>、<code>font.body</code></li><li>本專案 Tailwind/CSS：<code>--primary</code>、<code>--spacing-sm</code>、<code>--font-body</code> 等（見 <code>app/tailwind.css</code>）</li><li>需明確定義 <strong>figma variable → repo CSS token</strong> 對應表，可放在 <code>specs/figma-token-mapping.md</code> 或同目錄下規格檔，供 AI 與人工依規則更新 <code>app/tailwind.css</code>。</li></ul><h3 id="_3-2-semantic-vs-raw-token" tabindex="-1">3.2 Semantic vs raw token <a class="header-anchor" href="#_3-2-semantic-vs-raw-token" aria-label="Permalink to &quot;3.2 Semantic vs raw token&quot;">​</a></h3><ul><li>兩層 token：primitive（如 <code>blue-500</code>）→ semantic（如 <code>primary</code>）。</li><li>Figma 與 repo 雙邊是否一致，需在 design token schema 與 mapping 中定義；見 <a href="./../DESIGN_SYSTEM.html">DESIGN_SYSTEM.md</a> 的 Brand / Semantic 說明。</li></ul><h3 id="_3-3-mode-support" tabindex="-1">3.3 Mode support <a class="header-anchor" href="#_3-3-mode-support" aria-label="Permalink to &quot;3.3 Mode support&quot;">​</a></h3><ul><li>Figma variables 支援 light / dark mode。</li><li>本專案 CSS 以 <code>:root</code> 與 <code>.dark</code> 區分（<code>app/tailwind.css</code>）；需在 mapping 或轉換規則中寫明 mode 對應方式（例如 Figma <code>mode: dark</code> → <code>.dark</code> 下的變數）。</li></ul><hr><h2 id="四、figma-→-ai-修改邊界-治理三風險" tabindex="-1">四、Figma → AI 修改邊界（治理三風險） <a class="header-anchor" href="#四、figma-→-ai-修改邊界-治理三風險" aria-label="Permalink to &quot;四、Figma → AI 修改邊界（治理三風險）&quot;">​</a></h2><p>會破壞 Design System 的往往不是「AI 生成 code」，而是 <strong>AI 讀到設計稿後開始補齊差異</strong>。若無明確約束，Agent 容易把設計稿當真實來源，在 repo 裡新增或調整結構。以下三點為最常見的破壞點與對應治理。</p><h3 id="_4-1-token-drift-設計-token-與程式-token-漂移" tabindex="-1">4.1 Token drift（設計 token 與程式 token 漂移） <a class="header-anchor" href="#_4-1-token-drift-設計-token-與程式-token-漂移" aria-label="Permalink to &quot;4.1 Token drift（設計 token 與程式 token 漂移）&quot;">​</a></h3><ul><li><strong>風險</strong>：MCP 提供 variables 時，AI 發現設計稿與 repo token 不一致（例如 Figma 有 <code>color.primary.550</code>，repo 只有 <code>--color-primary-500</code>），若無規則會傾向直接新增 token 以「符合設計」，導致 token 膨脹、semantic 與 primitive 混雜、Tailwind/CSS 變複雜。</li><li><strong>Token policy</strong>： <ul><li>AI <strong>只允許修改既有 token 的數值</strong>，<strong>不可新增 primitive token</strong>。</li><li>若設計稿出現 repo 未定義的 token，只能<strong>標記為待人工確認</strong>，不得自行新增。</li></ul></li><li>對應文件：design token schema、figma → token mapping；見 <a href="./../DESIGN_SYSTEM.html">DESIGN_SYSTEM.md</a>、本文件 §3。</li></ul><h3 id="_4-2-component-divergence-元件實作與設計規格分岔" tabindex="-1">4.2 Component divergence（元件實作與設計規格分岔） <a class="header-anchor" href="#_4-2-component-divergence-元件實作與設計規格分岔" aria-label="Permalink to &quot;4.2 Component divergence（元件實作與設計規格分岔）&quot;">​</a></h3><ul><li><strong>風險</strong>：Figma component spec 與實際 UI component 很少完全一致；設計稿可能有多種 padding、icon 位置，repo 只實作一部分。AI 若讀到 spec 會嘗試補齊 missing variants 或生成新 component，導致 design system API 變複雜或出現兩套行為。</li><li><strong>治理</strong>：design-system <strong>primitives</strong>（如 Button、Input）<strong>僅由人工維護</strong>。AI 若發現 spec 與實作差異，<strong>只能更新 token 或 component docs</strong>，<strong>不得新增 primitive variant 或新 primitive component</strong>。</li><li>對應：<code>app/components/ui/*</code> 為 primitives；見 <a href="./design-system.html">design-system</a> 分層。</li></ul><h3 id="_4-3-layout-authority-混亂" tabindex="-1">4.3 Layout authority 混亂 <a class="header-anchor" href="#_4-3-layout-authority-混亂" aria-label="Permalink to &quot;4.3 Layout authority 混亂&quot;">​</a></h3><ul><li><strong>風險</strong>：Figma frame 含 layout、spacing、responsive，repo 可能用 container system 或 utility class 實作。AI 若依 frame spec 直接生成 CSS 或 Tailwind class，易破壞既有 layout pattern（例如新增 ad-hoc margin、grid），長期使 layout system 失去一致性。</li><li><strong>治理</strong>：<strong>Layout 層排除在 MCP 導入範圍外</strong>。Figma MCP 只用於 <strong>token 與 component style</strong>，<strong>不用於 page layout</strong>。Agent 在 rules 或 prompt 中須明確限制：不依 Figma frame 生成或修改 layout 相關 class；layout 權威在 repo 的 container / 既有 pattern。</li></ul><h3 id="_4-4-ai-參與開發時的權威與-ci" tabindex="-1">4.4 AI 參與開發時的權威與 CI <a class="header-anchor" href="#_4-4-ai-參與開發時的權威與-ci" aria-label="Permalink to &quot;4.4 AI 參與開發時的權威與 CI&quot;">​</a></h3><ul><li><strong>人類主導模式</strong>（IDE 內 AI 建議、開發者確認）：變更皆經人工 review，Design System 較不易被破壞。</li><li><strong>Autonomous agent</strong>（AI 直接改多檔、開 PR）：須限制編輯範圍，例如僅允許修改 <code>app/tailwind.css</code>（token 值）、<code>docs/</code>、既有 component 實作內容，<strong>不得新增</strong> design-system primitive 或 primitive token。</li><li><strong>CI 作為治理</strong>：PR 若新增 design token 或 primitive component，CI 可標記為需人工審核；若修改 UI component，可跑 visual regression 或 snapshot test。所有變更仍須通過 repo 規則與 CI 檢查。</li></ul><hr><h2 id="五、導入順序-schema-→-mapping-→-mcp" tabindex="-1">五、導入順序（Schema → Mapping → MCP） <a class="header-anchor" href="#五、導入順序-schema-→-mapping-→-mcp" aria-label="Permalink to &quot;五、導入順序（Schema → Mapping → MCP）&quot;">​</a></h2><p>實務建議依序進行，避免「先上 MCP、AI 不知如何對應」：</p><ol><li><strong>Step 1</strong>：定義 <strong>design token schema</strong>（repo 內，可放 <code>specs/design-token-schema.md</code> 或本目錄）。內容包含：primitive / semantic、命名格式、mode（light/dark）。</li><li><strong>Step 2</strong>：定義 <strong>figma → token mapping</strong>（Figma variable 名稱/群組 對應到 repo 的 token 鍵與 CSS 變數）。可寫成表或 <code>specs/figma-token-mapping.md</code>。</li><li><strong>Step 3</strong>：再引入或開發 <strong>MCP server</strong>，並在 Cursor 設定 <code>.cursor/mcp.json</code>（見下節）。</li></ol><hr><h2 id="六、最小可行-figma-mcp-架構要點" tabindex="-1">六、最小可行 Figma MCP 架構要點 <a class="header-anchor" href="#六、最小可行-figma-mcp-架構要點" aria-label="Permalink to &quot;六、最小可行 Figma MCP 架構要點&quot;">​</a></h2><p>可作為後續實作或規格對齊用。</p><h3 id="mcp-server-structure" tabindex="-1">MCP server structure <a class="header-anchor" href="#mcp-server-structure" aria-label="Permalink to &quot;MCP server structure&quot;">​</a></h3><ul><li>單一 process：Figma API client + MCP protocol adapter。</li><li>環境變數：<code>FIGMA_ACCESS_TOKEN</code>、可選 <code>FIGMA_FILE_KEY</code>（或由 tool 參數傳入）。</li></ul><h3 id="tools-spec-唯讀" tabindex="-1">Tools spec（唯讀） <a class="header-anchor" href="#tools-spec-唯讀" aria-label="Permalink to &quot;Tools spec（唯讀）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tool</th><th>說明</th></tr></thead><tbody><tr><td><code>get_file(file_key?)</code></td><td>回傳檔案 meta / 節點樹摘要。</td></tr><tr><td><code>get_variables(file_key?)</code></td><td>回傳 variable 清單（名稱、類型、mode、值）。</td></tr><tr><td><code>get_component_spec(node_id | component_key)</code></td><td>回傳單一元件 spec（props、尺寸、樣式摘要），供對照 DESIGN_SYSTEM.md / ui 元件。</td></tr></tbody></table><h3 id="token-transform-責任歸屬" tabindex="-1">Token transform 責任歸屬 <a class="header-anchor" href="#token-transform-責任歸屬" aria-label="Permalink to &quot;Token transform 責任歸屬&quot;">​</a></h3><ul><li><strong>MCP 不做「寫入 repo」</strong>：MCP 只回傳 Figma 原始或輕度正規化資料。</li><li>轉換規則（figma variable → repo token）寫在 <strong>repo 內</strong>（例如 <code>specs/figma-token-mapping.md</code> 或小 script 規格），由 Cursor Agent 或人工依規則改 <code>app/tailwind.css</code> / token 設定。</li></ul><h3 id="cursor-config" tabindex="-1">Cursor config <a class="header-anchor" href="#cursor-config" aria-label="Permalink to &quot;Cursor config&quot;">​</a></h3><ul><li>專案級設定：<code>.cursor/mcp.json</code>，指向上述 MCP server（<code>command</code> 或 <code>streamableHttp</code>）。</li><li>README 或 runbook 註明：需設定 <code>FIGMA_ACCESS_TOKEN</code>；MCP 僅讀，不寫入 Figma。</li><li>使用方式見 <a href="./../runbooks/figma-to-deploy-workflow.html">figma-to-deploy-workflow</a>。</li></ul><h3 id="實作位置" tabindex="-1">實作位置 <a class="header-anchor" href="#實作位置" aria-label="Permalink to &quot;實作位置&quot;">​</a></h3><ul><li><strong>MCP server</strong>：<code>tools/figma-mcp/</code>（<code>server.mjs</code> + <code>package.json</code>）。<strong>倉庫根目錄</strong>使用 pnpm；此子目錄為<strong>獨立 npm 套件</strong>。執行方式：<code>npm run start --prefix tools/figma-mcp</code>（或於 <code>tools/figma-mcp</code> 內 <code>npm run start</code>），需 env <code>FIGMA_ACCESS_TOKEN</code>、可選 <code>FIGMA_FILE_KEY</code>。詳見 <a href="./../../tools/figma-mcp/README.html">tools/figma-mcp/README.md</a>。</li></ul><hr><h2 id="七、相關" tabindex="-1">七、相關 <a class="header-anchor" href="#七、相關" aria-label="Permalink to &quot;七、相關&quot;">​</a></h2><ul><li><a href="./../DESIGN_SYSTEM.html">DESIGN_SYSTEM.md</a>：Token canonical 在 repo、Core components</li><li><a href="./design-system.html">design-system</a>：半自動化 UI、設計稿與 token 同步為未來可選</li><li><a href="./../runbooks/figma-to-deploy-workflow.html">figma-to-deploy-workflow</a>：AI-assisted Design-to-Code Pipeline</li><li><a href="./../../AGENT_CAPABILITIES.html">AGENT_CAPABILITIES.md</a>：AI 不主動新增 UI component、僅可改 token/docs 等邊界</li></ul>',54)])])}const h=o(i,[["render",n]]);export{g as __pageData,h as default};
